import { DEFAULT_POLICIES, SCENARIOS, runScenario, reconcile, summarize, createSeedRuns, validateImport } from './engine.js';
import { runEvaluation } from './evaluation.js';
import { storageConfig } from './storage-config.js';

const $ = (q,root=document) => root.querySelector(q);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy = value => structuredClone(value);
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',ledger:'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5',lab:'M9 3h6 M10 3v6L4 19q-1 2 2 2h12q3 0 2-2L14 9V3 M7 15h10',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',check:'M4 12l5 5L20 6',checks:'M4 7l2 2 4-4 M13 7h7 M4 15l2 2 4-4 M13 15h7',arrow:'M5 12h14 M14 7l5 5-5 5',down:'M7 10l5 5 5-5',chevron:'M9 5l7 7-7 7',download:'M12 3v12 M7 10l5 5 5-5 M4 15v6h16v-6',upload:'M12 16V4 M7 9l5-5 5 5 M4 16v5h16v-5',play:'M8 4l12 8-12 8z',refresh:'M20 7v5h-5 M4 17v-5h5 M19 7a8 8 0 0 0-14-1 M5 17a8 8 0 0 0 14 1',activity:'M3 12h4l3-8 4 16 3-8h4',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5z M10 21h4',help:'M9 8a3 3 0 1 1 5 2c-1 1-2 1-2 4 M12 18h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',close:'M6 6l12 12 M18 6 6 18',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',alert:'M12 3 2 21h20z M12 9v5 M12 18h.01',branch:'M6 3v13a4 4 0 0 0 8 0V8 M3 3h6 M11 8h6 M14 8l5-5',priority:'M4 17h4 M4 12h8 M4 7h12 M18 11v10 M15 14l3-3 3 3',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',code:'M8 6l-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',layers:'M12 3 2 8l10 5 10-5z M2 12l10 5 10-5 M2 16l10 5 10-5',menu:'M3 6h18 M3 12h18 M3 18h18',plus:'M12 4v16 M4 12h16',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',cloud:'M6 18a5 5 0 1 1 1-10 6 6 0 0 1 12 2 4 4 0 1 1 0 8z'};
const icon = (name,cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.layers}"/></svg>`;
const labels={fulfilled:'Fulfilled',missed:'Missed',unverified:'Unverified',waived:'Waived',pending:'Pending',not_applicable:'Not applicable'};
const kindLabels={mandatory:'Mandatory',resilience:'Resilience',priority:'Priority',progress:'Progress',decision:'Decision'};
const kindIcons={mandatory:'shield',resilience:'branch',priority:'priority',progress:'layers',decision:'branch'};
const scenarioTitles={healthy:'Healthy onboarding',skipped_guardrail:'Skipped guardrail',missing_telemetry:'Missing evidence',fallback_rescue:'Fallback rescue',priority_ignored:'Priority overlooked',priority_exception:'Approved priority exception',deadlock:'Blocked dependencies',late_guardrail:'Late guardrail',waived_guardrail:'Authorized waiver',telemetry_discrepancy:'Action without a log',pending_obligation:'Pending obligation'};
const scenarioNotes={healthy:'Every obligation has supporting evidence.',skipped_guardrail:'Activation succeeds without the required check.',missing_telemetry:'An evidence gap cannot prove an omission.',fallback_rescue:'A backup preserves a successful outcome.',priority_ignored:'Eligible higher-value work is passed over.',priority_exception:'An approved exception explains the choice.',deadlock:'No modeled transition can make progress.',late_guardrail:'A check runs after the protected action.',waived_guardrail:'An explicit authorized exception applies.',telemetry_discrepancy:'The gateway confirms the unlogged action.',pending_obligation:'A live obligation has not become due.'};
const scenarioIcons={healthy:'check',skipped_guardrail:'shield',missing_telemetry:'eye',fallback_rescue:'branch',priority_ignored:'priority',priority_exception:'checks',deadlock:'layers',late_guardrail:'clock',waived_guardrail:'check',telemetry_discrepancy:'activity',pending_obligation:'clock'};
const storage=storageConfig(import.meta.url);
const KEY=storage.ledgerKey;
let state,mode='browser',page=(location.hash.slice(1)||'overview'),filters={q:'',status:'all',kind:'all'},ledgerPage=1,selectedScenario='skipped_guardrail',labRunId=null,evaluation=null,busy=false,toastTimer,activeTrigger=null;
const pageTitles={overview:'Overview',ledger:'Opportunity ledger',lab:'Experiment lab',policies:'Policies',validation:'Validation',about:'How it works'};
if(!pageTitles[page])page='overview';
const allReceipts=()=>state.runs.flatMap(run=>(run.receipts||[]).map(receipt=>({...receipt,run})));
const activeReceipts=()=>allReceipts().filter(r=>r.status==='missed'||r.status==='unverified'||r.rescued||r.execution==='rescued');
const time = value => Number.isFinite(Date.parse(value))?new Date(value).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}):'—';
const preciseTime = value => Number.isFinite(Date.parse(value)) ? new Date(value).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit',fractionalSecondDigits:3,hour12:false}) : '—';
const date = value => Number.isFinite(Date.parse(value))?new Date(value).toLocaleDateString([], {day:'numeric',month:'short'}):'—';
const pct = n => `${Number(n||0).toFixed(Number(n||0)%1?1:0)}%`;
const badge = (status,rescued=false) => `<span class="badge ${rescued?'rescued':esc(status)}">${rescued?'Rescued':esc(labels[status]||status)}</span>`;
function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('toast-visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('toast-visible'),4200)}
async function persist(next){
 if(mode==='server'){
  const response=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(next)});
  if(!response.ok){const err=await response.json().catch(()=>({}));throw new Error(err.error||'The local server could not save this change.');}
  state=await response.json();
 } else {if(mode!=='memory')localStorage.setItem(KEY,JSON.stringify(next));state=next;}
}
function record(next,message){next.activity=[{at:new Date().toISOString(),message},...(next.activity||[])].slice(0,200)}
async function recoverBrowserLedger(){
 mode='browser';
 try{const old=localStorage.getItem(KEY);if(old)downloadText(old,'uncounted-recovery.json');localStorage.removeItem(KEY)}catch{mode='memory'}
 try{sessionStorage.setItem(storage.browserOnlyKey,'true')}catch{}
 state={schemaVersion:1,runs:await createSeedRuns(),policies:copy(DEFAULT_POLICIES),activity:[],seededAt:new Date().toISOString()};
 try{await persist(state)}catch{mode='memory'}
 render();
 if(mode==='memory')notify('Browser storage is unavailable. Export your ledger before closing or refreshing this page.');
}
async function init(){
 try{
  let forceBrowser=false;
  try{forceBrowser=sessionStorage.getItem(storage.browserOnlyKey)==='true'}catch{}
  let response=forceBrowser||!storage.discoverLocalServer?null:await fetch('/api/health',{signal:AbortSignal.timeout(2500)}).catch(()=>null);
  if(response?.ok){const health=await response.json().catch(()=>null);if(health?.mode==='server'){mode='server';const res=await fetch('/api/state');if(!res.ok)throw new Error('The local ledger could not be loaded.');state=await res.json();}}
  if(!state&&!forceBrowser&&storage.discoverLocalServer)throw new Error('The local server is unavailable. Retry when it is running, or explicitly open a separate browser-only ledger.');
  if(!state){let saved;try{saved=localStorage.getItem(KEY)}catch{mode='memory'}if(saved){let raw=JSON.parse(saved);const parsed=validateImport(raw);state={...parsed,activity:raw.activity||[],seededAt:raw.seededAt};}}
  if(!state){state={schemaVersion:1,runs:await createSeedRuns(),policies:copy(DEFAULT_POLICIES),activity:[],seededAt:new Date().toISOString()};record(state,'Created the AcmeCloud sandbox workspace.');try{await persist(state)}catch{mode='memory'}}
  render();
  if(mode==='memory')notify('Browser storage is unavailable. Export your ledger before closing or refreshing this page.');
 }catch(error){$('#app').innerHTML=`<div class="boot"><span class="logo-mark">u<span>·</span></span><h2>The ledger could not be opened</h2><p>${esc(error.message)}</p><div style="display:flex;gap:10px"><button class="btn primary" id="retry">Retry</button><button class="btn" id="recover">Start a browser-only ledger</button></div><p>Your previous browser data will be downloaded before resetting.</p></div>`;$('#retry').onclick=()=>location.reload();$('#recover').onclick=recoverBrowserLedger;}
}
function render(){
 const metrics=summarize(state.runs);
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar" aria-label="Main navigation"><a href="#overview" class="brand"><span class="logo-mark">u<span>·</span></span>UNCOUNTED</a><div class="brand-sub">Every outcome, accounted for</div><div class="workspace"><span class="avatar">A</span><div><strong>AcmeCloud</strong><small>Onboarding workspace</small></div>${icon('down')}</div><div class="nav-label">WORKSPACE</div><nav class="nav">${[['overview','grid','Overview'],['ledger','ledger','Opportunity ledger'],['lab','lab','Experiment lab'],['policies','shield','Policies'],['validation','checks','Validation']].map(([key,i,title])=>`<button data-nav="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(i)}${title}${key==='ledger'?`<span class="count">${metrics.missedObligations+metrics.unverifiedObligations}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-note"><span class="live-dot"></span>Instrumented sandbox<p>Real reconciliation.<br>Fictional business workflows.</p></div><button class="text-btn" data-nav="about" style="color:#a4bca8;margin-top:12px;font-size:11px">${icon('help')}How it works</button><div class="side-footer"><span class="avatar">AC</span>AcmeCloud workspace${icon('lock')}</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span>Workspace</span><span style="color:#b8c0af">/</span><b>${pageTitles[page]}</b></div><div class="topbar-right"><span class="demo-badge">${icon('lab')}Sandbox data</span><button class="icon-btn" data-action="activity" aria-label="View workspace activity">${icon('activity')}</button><span class="avatar" style="width:27px;height:27px;font-size:9px;border-radius:50%">AC</span></div></header><div class="content">${({overview:overview,ledger:ledger,lab:lab,policies:policies,validation:validation,about:about})[page](metrics)}<footer class="page-footer"><span>${icon('lock')}${mode==='server'?'Saved to your local server':mode==='memory'?'Temporary session — export to keep your ledger':'Saved in this browser'} · AcmeCloud sandbox</span><span>EXPECT <span>→</span> OBSERVE <span>→</span> ACCOUNT</span></footer></div></main></div>`;
 bind();
}
function heading(eyebrow,title,sub,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function defaultActions(){return `<button class="btn" data-action="export">${icon('download')}Export evidence</button><button class="btn primary" data-nav="lab">${icon('play')}Run experiment</button>`}
function overview(m){
 const receipts=activeReceipts().sort((a,b)=>Date.parse(b.run.startedAt)-Date.parse(a.run.startedAt)).slice(0,5);
 const known=(m.states.fulfilled||0)+(m.states.missed||0)+(m.states.waived||0),unknown=m.states.unverified||0,pending=m.states.pending||0,total=known+unknown+pending;
 const coverage=total?known/total*100:0,unknownPct=total?unknown/total*100:0;
 return heading('ACCOUNTABILITY LAYER','Operational overview','A clearer view of what happened. And what should have.',defaultActions())+`
 <section class="overview-intro"><div class="intro-copy"><p class="eyebrow">BEYOND THE SUCCESS RATE</p><h2>A successful request.<br> Not always the whole story.</h2><p>Account for every obligation behind your agents’ outcomes.</p></div><div class="health-summary"><div class="health-header"><span>APPLICATION VIEW</span><strong><span class="live-dot" style="background:#76a36a"></span>${m.successRate>=90?'Requests are succeeding':'Sandbox execution health'}</strong></div><div class="health-values"><div><b>${pct(m.successRate)}</b><small>Workflow success · ${m.successfulRuns}/${m.totalRuns}</small></div><div><b>${(m.p95LatencyMs/1000).toFixed(2)}<span style="font-size:14px">s</span></b><small>P95 · synthetic clock</small></div><div><b>${m.totalRuns}</b><small>Recorded executions</small></div></div></div></section>
 <div class="metric-grid">${metric('Missed obligations',m.missedObligations,`${m.eligibleObligationsDue} eligible obligations due`,'shield','missed','mandatory')}${metric('Unverified obligations',m.unverifiedObligations,'Evidence still needs to account for these','eye','unverified','mandatory')}${metric('Fallback dependence',pct(m.recoveryDependence),`${m.rescuedRuns} of ${m.fallbackEligibleRuns} eligible requests`,'branch','rescued','resilience')}${metric('Priority deferrals',m.priorityDeferred,'Eligible higher-value work deferred','priority','missed','priority')}</div>
 <div class="dashboard-middle"><section class="panel"><div class="panel-head"><div><h2>What the ledger reveals</h2><p>Unresolved obligations across recorded executions</p></div><span class="tag">Last ${m.totalRuns} runs</span></div>${chart()}</section><section class="panel coverage-panel"><div class="panel-head"><div><h2>Evidence coverage</h2><p>Applicable opportunities, by certainty</p></div>${icon('eye')}</div><div class="coverage-body"><div class="ring" style="background:conic-gradient(#527147 0 ${coverage}%,#d9bf76 ${coverage}% ${coverage+unknownPct}%,#dfe7d7 ${coverage+unknownPct}% 100%)"><div class="ring-center"><strong>${Math.round(coverage)}%</strong><small>accounted for</small></div></div><div class="coverage-legend"><div><span class="legend-dot" style="background:#527147"></span>Established<b>${known}</b></div><div><span class="legend-dot" style="background:#d9bf76"></span>Unverified<b>${unknown}</b></div><div><span class="legend-dot" style="background:#dfe7d7"></span>Pending<b>${pending}</b></div></div></div><p class="coverage-note">Established = fulfilled, missed, or authorized waiver.<br>Not applicable opportunities are excluded.</p></section></div>
 <section class="panel table-panel"><div class="panel-head"><div><h2>Needs a closer look <span class="tag" style="margin-left:7px">${activeReceipts().length}</span></h2><p>Every finding comes with an expectation and its evidence.</p></div><button class="text-btn" data-nav="ledger">View ledger ${icon('arrow')}</button></div>${receiptTable(receipts)}<div class="table-footer"><span>Generated from actual sandbox execution events</span><span>No missing-log assumptions</span></div></section>`;
}
function metric(label,value,note,i,status,kind){return `<button class="metric" data-filter-status="${status}" data-filter-kind="${kind}"><span class="metric-label">${label}${icon(i)}</span><div class="metric-value">${value}</div><div class="metric-note"><span class="tiny-dot"></span>${note}</div></button>`}
function chart(){
 const runs=[...state.runs].sort((a,b)=>Date.parse(a.startedAt)-Date.parse(b.startedAt));const size=Math.max(1,Math.ceil(runs.length/8)),bins=[];
 for(let i=0;i<runs.length;i+=size){const group=runs.slice(i,i+size);bins.push({label:`${i+1}–${Math.min(i+size,runs.length)}`,missed:group.reduce((v,r)=>v+r.receipts.filter(x=>x.kind==='mandatory'&&x.status==='missed').length,0),unverified:group.reduce((v,r)=>v+r.receipts.filter(x=>x.kind==='mandatory'&&x.status==='unverified').length,0),rescued:group.filter(r=>r.receipts.some(x=>x.rescued||x.execution==='rescued')).length})}
 const max=Math.max(4,...bins.map(b=>b.missed+b.unverified+b.rescued));return `<div class="chart-wrap"><div class="chart-legend"><span><i class="legend-dot" style="background:#b98972"></i>Confirmed miss</span><span><i class="legend-dot" style="background:#d9c17e"></i>Unverified</span><span><i class="legend-dot" style="background:#9eb98a"></i>Rescued</span></div><div class="chart" role="img" aria-label="Counts of missed obligations, unverified obligations and rescued requests by groups of recorded runs"><div class="y-axis"><span>${max}</span><span>${Math.round(max*2/3)}</span><span>${Math.round(max/3)}</span><span>0</span></div><div class="bar-plot">${bins.map(b=>`<div class="bar-group" title="Runs ${b.label}: ${b.missed} missed, ${b.unverified} unverified, ${b.rescued} rescued"><div class="bar-stack" style="height:calc((100% - 24px) * ${(b.missed+b.unverified+b.rescued)/max})"><i style="flex:${b.missed};background:#b98972"></i><i style="flex:${b.unverified};background:#d9c17e"></i><i style="flex:${b.rescued};background:#9eb98a"></i></div><small>${b.label}</small></div>`).join('')}</div></div><p class="chart-foot">Run cohorts · separate measures; a rescued request may also contain an unresolved obligation.</p></div>`;
}
function receiptTable(receipts){if(!receipts.length)return `<div class="empty">${icon('check')}<h3>Everything in this view is accounted for</h3><p>Try another filter or run a new experiment.</p></div>`;return `<div class="table-wrap"><table><thead><tr><th>Opportunity / expectation</th><th>Accounted outcome</th><th>Class</th><th>Owner</th><th>Execution</th><th></th></tr></thead><tbody>${receipts.map(r=>`<tr class="clickable" data-receipt="${esc(r.id)}" data-run="${esc(r.run.id)}"><td><button class="receipt-link" data-receipt="${esc(r.id)}" data-run="${esc(r.run.id)}"><strong>${esc(r.title)}</strong></button><small>${esc(r.run.customer)} · <span class="id-label">${esc(r.run.id)}</span></small></td><td>${badge(r.status,r.rescued||r.execution==='rescued')}</td><td>${esc(kindLabels[r.kind]||r.kind)}</td><td><span class="avatar-dot">${esc((r.owner||'UN').split(/\s/).map(x=>x[0]).slice(0,2).join(''))}</span>${esc(r.owner||'Unassigned')}</td><td><strong>${time(r.run.startedAt)}</strong><small>${date(r.run.startedAt)}</small></td><td class="row-arrow">${icon('chevron')}</td></tr>`).join('')}</tbody></table></div>`}
function ledger(){
 let rows=allReceipts().filter(r=>(filters.status==='all'||(filters.status==='rescued'?(r.rescued||r.execution==='rescued'):r.status===filters.status))&&(filters.kind==='all'||r.kind===filters.kind)&&`${r.title} ${r.id} ${r.run.id} ${r.run.customer} ${r.owner} ${r.reason}`.toLowerCase().includes(filters.q.toLowerCase())).sort((a,b)=>Date.parse(b.run.startedAt)-Date.parse(a.run.startedAt));const pages=Math.max(1,Math.ceil(rows.length/12));ledgerPage=Math.min(ledgerPage,pages);return heading('THE OPPORTUNITY LEDGER','Every expectation has a receipt.','Inspect the evidence that connects what was required to what occurred.',`<button class="btn" data-action="import">${icon('upload')}Import ledger</button><button class="btn primary" data-action="export">${icon('download')}Export JSON</button>`)+`<div class="toolbar"><label class="searchbox">${icon('search')}<input id="ledger-search" aria-label="Search the ledger" placeholder="Search expectations, customers, run IDs…" value="${esc(filters.q)}"></label><select id="status-filter" class="select" aria-label="Filter by outcome"><option value="all">All outcomes</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${filters.status===k?'selected':''}>${v}</option>`).join('')}<option value="rescued" ${filters.status==='rescued'?'selected':''}>Rescued</option></select><select id="kind-filter" class="select" aria-label="Filter by class"><option value="all">All classes</option>${Object.entries(kindLabels).filter(([k])=>k!=='decision').map(([k,v])=>`<option value="${k}" ${filters.kind===k?'selected':''}>${v}</option>`).join('')}</select><button class="btn" data-action="reconcile">${icon('refresh')}Reconcile</button></div><section class="panel table-panel">${receiptTable(rows.slice((ledgerPage-1)*12,ledgerPage*12))}<div class="table-footer"><span>${rows.length} matching receipts · ${allReceipts().length} total</span><div class="pagination"><button data-action="prev-page" aria-label="Previous page" ${ledgerPage===1?'disabled':''}>←</button><span>${ledgerPage} / ${pages}</span><button data-action="next-page" aria-label="Next page" ${ledgerPage===pages?'disabled':''}>→</button></div></div></section><p class="trust-note">A “missed” mandatory obligation requires authoritative evidence. Rescued requests remain fulfilled; priority findings remain bounded to the recorded eligibility and policy assumptions.</p>`;
}
function lab(){const scenario=SCENARIOS.find(s=>s.id===selectedScenario)||SCENARIOS[0],run=state.runs.find(r=>r.id===labRunId);return heading('CONTROLLED EXECUTIONS','Experiment lab','Run the workflow. Watch the evidence. Inspect the hidden outcome.',`<button class="btn" data-action="run-batch">${icon('layers')}Run all scenarios</button>`)+`<div class="lab-grid"><div><p class="eyebrow" style="margin-bottom:13px">CHOOSE AN EXPERIMENT</p><div class="scenario-list">${SCENARIOS.map(s=>`<button class="scenario-option ${s.id===selectedScenario?'selected':''}" data-scenario="${esc(s.id)}" aria-pressed="${s.id===selectedScenario}"><span class="scenario-icon">${icon(scenarioIcons[s.id]||'lab')}</span><span><strong>${esc(scenarioTitles[s.id]||s.title)}</strong><small>${esc(scenarioNotes[s.id]||s.description)}</small></span></button>`).join('')}</div></div><section class="panel lab-main"><div class="lab-banner"><span class="eyebrow">ACMECLOUD / ONBOARDING AGENT</span><h2>${esc(scenarioTitles[scenario.id]||scenario.title)}</h2><p>${esc(scenario.description)}</p></div><div class="execution-flow"><div class="flow-node">${icon('cloud')}Receive request</div><span class="flow-arrow">→</span><div class="flow-node">${icon('shield')}Evaluate policy</div><span class="flow-arrow">→</span><div class="flow-node">${icon('layers')}Activate account</div><span class="flow-arrow">→</span><div class="flow-node">${icon('ledger')}Account</div></div><div class="lab-controls"><p>Instrumented JavaScript services<br>Synthetic conditions · actual event reconciliation</p><button class="btn primary" data-action="run-scenario" ${busy?'disabled':''}>${icon(busy?'refresh':'play',busy?'spin':'')}${busy?'Executing…':'Run experiment'}</button></div><div class="lab-result">${run?labResult(run):`<div class="empty" style="padding:33px 15px">${icon('activity')}<h3>The evidence starts here.</h3><p>Run this scenario to create a new workflow<br>and independently reconcile its obligations.</p></div>`}</div></section></div>`}
function labResult(run){const relevant=run.receipts.filter(r=>r.status!=='not_applicable');return `<div class="run-meta"><span class="id-label">${esc(run.id)}</span><span class="badge ${run.outcome==='success'?'fulfilled':'pending'}">${run.outcome==='success'?'Application succeeded':'Workflow '+esc(run.outcome)}</span></div>${timeline(run.events)}${relevant.map(r=>`<div class="finding">${badge(r.status,r.rescued||r.execution==='rescued')}<h3>${esc(r.title)}</h3><p>${esc(r.reason)}</p><button class="text-btn" data-receipt="${esc(r.id)}" data-run="${esc(run.id)}">Inspect receipt ${icon('arrow')}</button></div>`).join('')}`}
function timeline(events){return `<ol class="timeline">${events.map(e=>`<li class="${e.type.includes('expected')?'expected':''}"><time>${preciseTime(e.at)}</time><strong>${esc(e.type.replaceAll('.',' › ').replaceAll('_',' '))}</strong><small>${esc(e.source)}${e.authoritative?' · authoritative sandbox record':''}</small><details class="event-payload"><summary>Inspect event data</summary><pre class="code-view">${esc(JSON.stringify(e.data,null,2))}</pre></details></li>`).join('')}</ol>`}
function policies(){return heading('DECLARED INTENT','Policies & expectations','Approved rules make obligations explicit before execution.',`<span class="tag">${state.policies.filter(p=>p.enabled&&p.approved).length} active policies</span>`)+`<div class="section-note">${icon('info')}<span>Policy changes apply to future runs. Each historical receipt retains the policy version used at execution.</span></div><div class="policies-grid">${state.policies.map(p=>`<article class="policy-card"><div class="policy-top"><span class="policy-icon">${icon(kindIcons[p.kind])}</span><span class="badge ${p.approved?'fulfilled':'pending'}">${p.approved?'Approved':'Draft'} · v${esc(p.version)}</span></div><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><div class="rule-block"><b>CLASS</b> ${esc(kindLabels[p.kind])}<br><b>EXPECT</b> ${esc(p.expectedAction||p.action||'Policy-specific evidence')}<br><b>BEFORE</b> ${esc(p.beforeAction||'Workflow completion')}<br><b>SOURCE</b> ${esc(p.evidenceSource||'Instrumented services')}</div><div class="policy-footer"><span>Owner: ${esc(p.owner||'Platform team')}</span><button class="text-btn" data-edit-policy="${esc(p.id)}">Review rule ${icon('arrow')}</button></div><div style="display:flex;justify-content:space-between;margin-top:17px"><span class="id-label">${esc(p.id)}</span><button class="toggle ${p.enabled?'on':''}" data-toggle-policy="${esc(p.id)}" role="switch" aria-checked="${!!p.enabled}" aria-label="Enable ${esc(p.name)}"><i></i>${p.enabled?'Active':'Paused'}</button></div></article>`).join('')}</div><p class="trust-note">This MVP uses four explicit deterministic rule types. Rule descriptions and revisions are human-reviewed; natural-language rule generation and external model calls are not connected.</p>`}
function validation(){let e=evaluation;return heading('MEASURED, NOT ASSUMED','Validation workbench','Reproducible fixtures. Independent expectations. Honest uncertainty.')+`<section class="panel"><div class="validation-hero"><div><p class="eyebrow">THE CREDIBILITY TEST</p><h2>An omitted action is not an unobserved action.</h2><p>The suite checks omissions, evidence gaps, valid exceptions, recovery, ordering, and blocked progress against independently authored ground truth.</p></div><button class="btn primary" data-action="evaluate" ${busy?'disabled':''}>${icon(busy?'refresh':'play',busy?'spin':'')}${busy?'Evaluating…':e?'Run again':'Run validation'}</button></div></section>${e?`<div class="validation-cards">${validationStat(`${e.passed}/${e.total}`,'Classification checks passed','Independent event fixtures')}${validationStat(pct(e.metrics.precision * 100),'Confirmed omission precision','Claims supported by ground truth')}${validationStat(pct(e.metrics.recall * 100),'True omission recall','Includes unobservable omissions')}${validationStat(pct(e.metrics.unverifiedAccuracy * 100),'Unverified accuracy','Evidence gaps retained')}</div><div class="section-note">${icon('info')}<span>Recall can be below 100% by design: omissions without sufficient evidence remain unverified. ${pct(e.metrics.supportedRecall * 100)} recall on omissions with authoritative evidence. ${pct(e.metrics.falsePositiveRate * 100)} false-positive rate. Evaluation took ${Number(e.elapsedMs||0).toFixed(1)} ms locally; this is not a production benchmark.</span></div><section class="panel table-panel"><div class="panel-head"><div><h2>Independent validation results</h2><p>${e.total} cases · ${e.failed} failures</p></div><button class="text-btn" data-action="export-evaluation">Export report ${icon('download')}</button></div><div class="table-wrap"><table><thead><tr><th>Test case</th><th>Expected</th><th>Actual</th><th>Result</th></tr></thead><tbody>${e.cases.map(c=>`<tr><td><strong>${esc(c.name)}</strong>${c.detail?`<small>${esc(c.detail)}</small>`:''}</td><td>${esc(c.expected)}</td><td>${esc(c.actual)}</td><td><span class="badge ${c.passed?'fulfilled':'missed'}">${c.passed?'Passed':'Failed'}</span></td></tr>`).join('')}</tbody></table></div></section>`:`<div class="about-grid" style="margin-top:20px"><article class="about-card">${icon('shield')}<h3>Evidence-aware correctness</h3><p>Missing telemetry, wrong sources, wrong workflow identifiers, stale policies, timing constraints, and explicit exceptions are tested separately.</p></article><article class="about-card">${icon('layers')}<h3>Beyond a success flag</h3><p>Successful recovery stays fulfilled. Priority exceptions stay distinct. Dependency analysis checks reachable progress, not just cycles.</p></article></div>`}`}
function validationStat(value,label,note){return `<div class="validation-stat"><strong>${value}</strong><span>${label}</span><small>${note}</small></div>`}
function about(){return heading('THE UNCOUNTED PRINCIPLE','Success deserves a second look.','An accountability layer for the obligations behind autonomous outcomes.')+`<div class="about-grid"><article class="about-card wide"><p class="eyebrow">A SMALL, RIGOROUS CORE</p><h2>From declared intent to an inspectable receipt.</h2><div class="step-grid"><div><span class="step-number">01 / EXPECT</span><h3>Declare the obligation</h3><p>Approved policies define what is required, where it applies, and which evidence can establish fulfillment.</p></div><div><span class="step-number">02 / OBSERVE</span><h3>Capture the evidence</h3><p>Instrumented sandbox services emit workflow events and gateway records at meaningful decision boundaries.</p></div><div><span class="step-number">03 / ACCOUNT</span><h3>Reconcile the outcome</h3><p>A deterministic engine matches the evidence to each expectation and creates a reasoned, inspectable receipt.</p></div></div></article><article class="about-card">${icon('ledger')}<h3>Six states, no invented certainty</h3><p>Fulfilled, missed, waived, pending, unverified, and not applicable. Every declared opportunity has one state. Degradation and successful rescue are recorded separately.</p><p>“Silent Outcome Debt” is the source concept’s name for unresolved exposure, not a financial metric or an established reliability standard. This app shows distinct counts and denominators.</p></article><article class="about-card">${icon('lab')}<h3>A working, bounded sandbox</h3><p>Each experiment executes real JavaScript service functions with synthetic conditions. The dashboard is calculated from their resulting evidence, not prewritten findings.</p><p>The workspace does not connect to production agents, verify cryptographic signatures, or call an AI model. Authority is modeled inside the sandbox; production evidence requires authenticated collectors.</p></article><article class="about-card">${icon('lock')}<h3>Your data & persistence</h3><p>${mode==='server'?'This edition saves to an atomic JSON store on your local server.':mode==='memory'?'Browser storage is unavailable. This temporary ledger is lost when you close or refresh the page.':'This hosted edition saves in your browser’s local storage. Clearing site data removes your ledger.'} Export a JSON backup to preserve or move your work. The downloadable project includes a local Node server and disk persistence.</p><div style="display:flex;gap:8px"><button class="btn small" data-action="export">${icon('download')}Export backup</button><button class="btn small" data-action="import">${icon('upload')}Import backup</button></div></article><article class="about-card">${icon('refresh')}<h3>Start another demonstration</h3><p>Resetting reruns the initial scenario mixture and restores the original approved policies. Export your current ledger first if you want to keep it.</p><button class="btn small" data-action="reset">${icon('refresh')}Reset sandbox</button></article></div>`}
function bind(){
 document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>navigate(el.dataset.nav));
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>act(el.dataset.action));
 document.querySelectorAll('[data-filter-status]').forEach(el=>el.onclick=()=>{filters.status=el.dataset.filterStatus;filters.kind=el.dataset.filterKind;filters.q='';ledgerPage=1;navigate('ledger')});
 document.querySelectorAll('[data-receipt]').forEach(el=>el.onclick=ev=>{ev.stopPropagation();showReceipt(el.dataset.run,el.dataset.receipt)});
 document.querySelectorAll('[data-scenario]').forEach(el=>el.onclick=()=>{selectedScenario=el.dataset.scenario;labRunId=null;render()});
 document.querySelectorAll('[data-edit-policy]').forEach(el=>el.onclick=()=>editPolicy(el.dataset.editPolicy));
 document.querySelectorAll('[data-toggle-policy]').forEach(el=>el.onclick=()=>togglePolicy(el.dataset.togglePolicy));
 if($('#ledger-search'))$('#ledger-search').oninput=ev=>{const caret=ev.target.selectionStart;filters.q=ev.target.value;ledgerPage=1;render();$('#ledger-search').focus();$('#ledger-search').setSelectionRange(caret,caret)};
 if($('#status-filter'))$('#status-filter').onchange=ev=>{filters.status=ev.target.value;ledgerPage=1;render()};
 if($('#kind-filter'))$('#kind-filter').onchange=ev=>{filters.kind=ev.target.value;ledgerPage=1;render()};
}
function navigate(target){page=target;location.hash=target;render();window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(pageTitles[next]&&next!==page){page=next;render()}});
async function act(action){
 if(busy&&['import','reset','run-scenario','run-batch','reconcile','evaluate'].includes(action))return;
 if(action==='menu'){$('.sidebar').classList.toggle('open');return}
 if(action==='export'){downloadJSON(state,`uncounted-ledger-${new Date().toISOString().slice(0,10)}.json`);notify('Ledger and evidence exported.');return}
 if(action==='import'){$('#import-file').click();return}
 if(action==='activity'){showActivity();return}
 if(action==='prev-page'){ledgerPage--;render();return}if(action==='next-page'){ledgerPage++;render();return}
 if(action==='export-evaluation'){downloadJSON(evaluation,'uncounted-evaluation.json');return}
 if(action==='reset'){showReset();return}
 if(busy)return;
 busy=true;
 try{
  if(action==='run-scenario'||action==='run-batch'){
   render();await new Promise(r=>setTimeout(r,180));const next=copy(state);const chosen=action==='run-batch'?SCENARIOS.map(s=>s.id):[selectedScenario];let last;
   for(const id of chosen){last=await runScenario(id,{policies:next.policies,now:new Date().toISOString()});next.runs.push(last)}
   record(next,`${chosen.length===1?'Executed '+(scenarioTitles[selectedScenario]||selectedScenario):'Executed all '+chosen.length+' scenarios'}.`);await persist(next);labRunId=last.id;
   notify(chosen.length===1?'Workflow executed. Evidence reconciled.':`${chosen.length} workflows executed and accounted for.`);
  }
  if(action==='reconcile'){
   const next=copy(state);let changes=0;next.runs.forEach(run=>{const result=reconcile(run,run.policySnapshot||next.policies);changes+=result.filter((r,i)=>r.status!==run.receipts[i]?.status).length;run.receipts=result});record(next,`Reconciled ${next.runs.length} workflows; ${changes} outcome changes.`);await persist(next);notify(`${next.runs.length} workflows reconciled · ${changes} changed outcomes.`);
  }
  if(action==='evaluate'){render();await new Promise(r=>setTimeout(r,50));evaluation=await runEvaluation();notify(`${evaluation.passed} of ${evaluation.total} independent checks passed.`)}
 }catch(error){notify(`Could not complete: ${error.message}`)}finally{busy=false;render()}
}
function showOverlay(html,modal=false){activeTrigger=document.activeElement;$('#overlay').innerHTML=`<div class="backdrop ${modal?'modal-backdrop':''}"><section class="${modal?'modal':'drawer'}" role="dialog" aria-modal="true" aria-label="${modal?'Workspace action':'Opportunity receipt'}" tabindex="-1">${html}</section></div>`;$('.backdrop').onclick=e=>{if(e.target===e.currentTarget)closeOverlay()};$('#overlay').querySelectorAll('[data-close]').forEach(b=>b.onclick=closeOverlay);$('.modal,.drawer').focus();}
function closeOverlay(){if(busy)return;$('#overlay').innerHTML='';activeTrigger?.focus()}
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeOverlay();$('.sidebar')?.classList.remove('open')}if(e.key==='Tab'&&$('.backdrop')){const focusable=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal,.drawer'))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
function showReceipt(runId,receiptId){const run=state.runs.find(r=>r.id===runId),r=run?.receipts.find(r=>r.id===receiptId);if(!r)return;const evidence=run.events.filter(e=>(r.evidenceIds||[]).includes(e.id));showOverlay(`<div class="drawer-top"><span class="eyebrow">OPPORTUNITY RECEIPT</span><button class="icon-btn" data-close aria-label="Close receipt">${icon('close')}</button></div>${badge(r.status)}${r.rescued||r.execution==='rescued'?` <span class="badge rescued">Successful rescue</span>`:''}<h2>${esc(r.title)}</h2><p class="subtitle">${esc(run.customer)} · ${esc(run.id)}</p><div class="receipt-facts"><div><small>Policy</small><strong>${esc(r.policyId)} · v${esc(r.policyVersion)}</strong></div><div><small>Class</small><strong>${esc(kindLabels[r.kind])}</strong></div><div><small>Owner</small><strong>${esc(r.owner)}</strong></div><div><small>Customer outcome</small><strong>${run.outcome==='success'?'Fulfilled':esc(run.outcome)}</strong></div></div><div class="account-section"><p class="eyebrow">01 / EXPECTED</p><p>${esc(r.expected)}</p></div><div class="account-section"><p class="eyebrow">02 / OBSERVED</p><p>${esc(r.observed)}</p></div><div class="account-section"><p class="eyebrow">03 / ACCOUNTED</p><p>${esc(r.reason)}</p>${r.assumptions?.length?`<p class="trust-note">Assumptions: ${r.assumptions.map(esc).join(' · ')}</p>`:''}</div><section class="evidence-box"><h3>Supporting evidence <span class="tag">${evidence.length} records</span></h3>${evidence.length?timeline(evidence):`<p class="trust-note">No qualifying evidence was available for this expectation.</p>`}</section><details style="margin-top:24px"><summary class="text-btn">Inspect structured receipt</summary><pre class="code-view">${esc(JSON.stringify(r,null,2))}</pre></details><button class="btn" id="download-receipt" style="margin-top:22px">${icon('download')}Export receipt & evidence</button><p class="trust-note">Synthetic AcmeCloud evidence. Source authority is modeled in the sandbox and is not a cryptographic verification.</p>`);$('#download-receipt').onclick=()=>downloadJSON({receipt:r,workflow:run,evidence},`${r.id}.json`)}
async function togglePolicy(id){if(busy)return;busy=true;try{const next=copy(state),p=next.policies.find(p=>p.id===id);p.enabled=!p.enabled;record(next,`${p.enabled?'Activated':'Paused'} policy ${p.id} v${p.version}.`);await persist(next);render();notify(`Policy ${p.enabled?'activated':'paused'} for future runs.`)}catch(e){notify(e.message)}finally{busy=false}}
function editPolicy(id){const p=state.policies.find(p=>p.id===id);showOverlay(`<div class="drawer-top"><p class="eyebrow">HUMAN-REVIEWED POLICY</p><button class="icon-btn" data-close aria-label="Close policy editor">${icon('close')}</button></div><h2>${esc(p.name)}</h2><p>The detector’s conditions stay explicit. Review this documentation and ownership revision, then approve it for future executions.</p><form id="policy-form"><div class="form-field"><label for="policy-version">New policy version</label><input id="policy-version" name="version" value="${esc(p.version)}" required maxlength="24" pattern="[A-Za-z0-9._-]+"></div><div class="form-field"><label for="policy-owner">Accountable owner</label><input id="policy-owner" name="owner" value="${esc(p.owner)}" required maxlength="80"></div><div class="form-field"><label for="policy-description">Policy description</label><textarea id="policy-description" name="description" required maxlength="1000">${esc(p.description)}</textarea></div><div class="rule-block"><b>EXPECT</b> ${esc(p.expectedAction)}<br><b>BEFORE</b> ${esc(p.beforeAction||'Workflow completion')}<br><b>EVIDENCE</b> ${esc(p.evidenceSource)}</div><p class="trust-note">This editor updates policy documentation, version, and owner. Changing executable detector logic requires editing the source. Historical evidence remains attached to its original version.</p><div id="policy-error" role="alert"></div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">${icon('check')}Approve revision</button></div></form>`,true);$('#policy-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const form=new FormData(e.target);if(form.get('version').trim()===p.version){$('#policy-error').innerHTML='<p class="notice-error">Use a new version to preserve the policy history.</p>';return}const button=e.submitter;button.disabled=true;busy=true;try{const next=copy(state),rule=next.policies.find(x=>x.id===id);Object.assign(rule,{version:form.get('version').trim(),owner:form.get('owner').trim(),description:form.get('description').trim(),approved:true});record(next,`Approved ${id} revision ${rule.version}.`);await persist(next);busy=false;closeOverlay();render();notify('Policy revision approved for future executions.')}catch(error){busy=false;if($('#policy-error'))$('#policy-error').innerHTML=`<p class="notice-error">${esc(error.message)}</p>`;else notify(error.message);button.disabled=false}}}
function showActivity(){showOverlay(`<div class="drawer-top"><p class="eyebrow">WORKSPACE ACTIVITY</p><button class="icon-btn" data-close aria-label="Close activity">${icon('close')}</button></div><h2>A record of your changes.</h2><p class="subtitle">Local workspace activity. Exported with your ledger.</p><ul class="activity-list">${(state.activity||[]).map(a=>`<li>${esc(a?.message||a||'Workspace activity')}<small>${date(a?.at)} ${time(a?.at)}</small></li>`).join('')||'<li>No workspace changes yet.</li>'}</ul>`)}
function showReset(){showOverlay(`<div class="drawer-top"><p class="eyebrow">RESET SANDBOX</p><button class="icon-btn" data-close aria-label="Close reset confirmation">${icon('close')}</button></div><h2>Start with a fresh ledger?</h2><p>This replaces your ${state.runs.length} recorded workflows and current policy revisions with the original AcmeCloud demonstration. Download a backup first to keep your work.</p><div class="modal-actions"><button class="btn" id="backup-reset">Export backup</button><button class="btn primary" id="confirm-reset">Reset sandbox</button></div>`,true);$('#backup-reset').onclick=()=>downloadJSON(state,'uncounted-backup.json');$('#confirm-reset').onclick=async()=>{if(busy)return;busy=true;try{$('#confirm-reset').disabled=true;const next={schemaVersion:1,runs:await createSeedRuns(),policies:copy(DEFAULT_POLICIES),activity:[],seededAt:new Date().toISOString()};record(next,'Reset sandbox to original scenario executions.');await persist(next);labRunId=null;busy=false;closeOverlay();render();notify('Sandbox reset. Fresh executions are ready.')}catch(e){busy=false;notify(e.message);if($('#confirm-reset'))$('#confirm-reset').disabled=false}}}
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadJSON(value,name){downloadText(JSON.stringify(value,null,2),name)}
$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>8*1024*1024)throw new Error('Choose a JSON ledger smaller than 8 MB.');const raw=JSON.parse(await file.text()),parsed=validateImport(raw),next={...parsed,activity:Array.isArray(raw.activity)?raw.activity.filter(a=>a&&typeof a==='object'&&typeof a.message==='string').slice(0,200):[],seededAt:Number.isFinite(Date.parse(raw.seededAt))?raw.seededAt:new Date().toISOString()};showOverlay(`<div class="drawer-top"><p class="eyebrow">IMPORT EVIDENCE LEDGER</p><button class="icon-btn" data-close aria-label="Cancel import">${icon('close')}</button></div><h2>${next.runs.length} workflows ready to import.</h2><p>Replace this workspace with <strong>${esc(file.name)}</strong>? Receipts are independently reconciled from the imported evidence; imported status labels are not trusted.</p><p class="trust-note">Imports are sandbox data. A declared source label does not authenticate a real external service.</p><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="confirm-import">Replace ledger</button></div>`,true);$('#confirm-import').onclick=async()=>{if(busy)return;busy=true;try{$('#confirm-import').disabled=true;record(next,`Imported ${next.runs.length} workflows from ${file.name}.`);await persist(next);labRunId=null;busy=false;closeOverlay();render();notify('Evidence imported and receipts reconciled.')}catch(err){busy=false;notify(err.message);if($('#confirm-import'))$('#confirm-import').disabled=false}}}catch(error){notify(`Import rejected: ${error.message}`)}};
init();
